#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Optional OpenMP header (only needed when compiling with -fopenmp). */
#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* Tunable OpenMP chunk size for the 1D spatial loops.
   This can be overridden at compile time, e.g.,
   -DJACOBI_1D_OMP_CHUNK_SIZE=256 */
#ifndef JACOBI_1D_OMP_CHUNK_SIZE
# define JACOBI_1D_OMP_CHUNK_SIZE 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i+ 2) / n;
      B[i] = ((DATA_TYPE) i+ 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified pointer aliases to help the compiler
     with alias analysis and vectorization.
   - Hoist loop-invariant quantities (_PB_TSTEPS, _PB_N, stencil
     coefficient) into local constants.
   - Parallelize the spatial loops with OpenMP (if enabled at compile
     time) and request SIMD vectorization via "for simd".
   - Keep the time-stepping loop sequential, as each step depends on
     the previous one.
*/
static
__attribute__((flatten, noinline))
void kernel_jacobi_1d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_1D(A,N,n),
		      DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Parameters tsteps and n are kept for interface compatibility;
     the PolyBench macros _PB_TSTEPS and _PB_N are used for the
     actual loop bounds. */
  (void)tsteps;
  (void)n;

  /* Local scalar copies of problem sizes.  Making them local const
     helps the compiler reason about them and can slightly improve
     optimization. */
  const int T  = _PB_TSTEPS;
  const int N_ = _PB_N;

  /* Restrict-qualified aliases improve alias analysis and allow the
     compiler to safely reorder and vectorize memory accesses.  The
     original PolyBench harness always passes distinct arrays here. */
  DATA_TYPE * __restrict__ A_ptr = A;
  DATA_TYPE * __restrict__ B_ptr = B;

  /* Stencil coefficient.  Using a double here preserves the original
     floating-point semantics, since the literal 0.33333 in the
     original code has type double.  The compiler will typically keep
     this in a register. */
  const double c = 0.33333;

#pragma scop
  /* Parallel region: each time step is executed sequentially, but the
     spatial loops over i are distributed over threads.  If compiled
     without OpenMP support, the pragmas are ignored and the code
     falls back to the original sequential behavior. */
#pragma omp parallel
  {
    for (int t = 0; t < T; ++t)
    {
      /* First sweep: compute B from A.
         "omp for simd" both parallelizes across threads and
         vectorizes across SIMD lanes when possible. */
#pragma omp for simd schedule(static, JACOBI_1D_OMP_CHUNK_SIZE)
      for (int i = 1; i < N_ - 1; ++i)
      {
        /* The arithmetic expression is kept identical to the original:
           double-precision constant times the sum of three neighboring
           elements, then converted back to DATA_TYPE on assignment. */
        B_ptr[i] = (DATA_TYPE)(
            c * (A_ptr[i-1] + A_ptr[i] + A_ptr[i+1])
        );
      }
      /* Implicit barrier at the end of "omp for simd" guarantees that
         all B[i] are updated before the second sweep starts. */

      /* Second sweep: compute A from B. */
#pragma omp for simd schedule(static, JACOBI_1D_OMP_CHUNK_SIZE)
      for (int i = 1; i < N_ - 1; ++i)
      {
        A_ptr[i] = (DATA_TYPE)(
            c * (B_ptr[i-1] + B_ptr[i] + B_ptr[i+1])
        );
      }
      /* Implicit barrier here ensures that all A[i] for the current
         time step are updated before the next time step begins. */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
