     32-byte aligned). This assumption is encoded explicitly here so
     that the compiler can safely generate aligned SIMD accesses. */
  A_ptr = (DATA_TYPE *) __builtin_assume_aligned(A_ptr, 32);
  B_ptr = (DATA_TYPE *) __builtin_assume_aligned(B_ptr, 32);

