static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Local restrict-qualified pointers improve the compiler's
   * ability to optimize and vectorize by removing potential
   * aliasing between A and B. */
  DATA_TYPE *restrict A_ = A;
  DATA_TYPE *restrict B_ = B;

