  A_ = __builtin_assume_aligned(A_, 64);
  B_ = __builtin_assume_aligned(B_, 64);

  /* Use the PolyBench-sanitized sizes for loop bounds. */
  const int pb_n      = _PB_N;
  const int pb_tsteps = _PB_TSTEPS;

  /* Interior points: [1, pb_n-2]. The upper bound below is
   * exclusive (i < i_end). */
  const int i_start = 1;
  const int i_end   = pb_n - 1;

  /* Keep the scalar coefficient as double, matching the
   * original literal `0.33333` and preserving floating-point
   * semantics even when DATA_TYPE is float. */
  const double c0 = 0.33333;

  int t, i;

#pragma scop
  /* Single OpenMP parallel region amortizes thread creation
   * cost. Each time step consists of two independent 1D
   * stencils which are parallelized over `i`. The implicit
   * barrier at the end of each `omp for` preserves the exact
   * sequential semantics of the original code. */
#pragma omp parallel default(none) private(t, i) shared(A_, B_, c0, pb_tsteps, i_start, i_end)
  {
    for (t = 0; t < pb_tsteps; ++t)
    {
      /* First sweep: compute B from A. Each iteration of this
       * loop only reads A and writes a distinct B[i], so it is
       * safe to parallelize. */
#pragma omp for schedule(static)
      for (i = i_start; i < i_end; ++i)
      {
