       * produced before this loop starts (implicit barrier at
       * end of previous `omp for`). Each iteration only writes
       * a distinct A[i], so this loop is also safely parallel. */
#pragma omp for schedule(static)
      for (i = i_start; i < i_end; ++i)
      {
        const DATA_TYPE b_im1 = B_[i - 1];
        const DATA_TYPE b_i   = B_[i];
        const DATA_TYPE b_ip1 = B_[i + 1];

        A_[i] = (DATA_TYPE)(c0 * (b_im1 + b_i + b_ip1));
      }
      /* Implicit barrier here keeps all threads synchronized
       * between time steps, exactly as in the original
       * sequential nest. */
